impl EmployeeModule {
    /// Create a new module builder
    pub fn builder() -> EmployeeModuleBuilder {
        EmployeeModuleBuilder::new()
    }

    /// Mount ALL generated CRUD endpoints (12 per entity) with NO domain
    /// validation — the fully **unguarded** surface. A well-formed request can
    /// create invalid rows or soft-delete a referenced master out from under its
    /// dependents. Prefer a guarded composition (read + validated writes) for any
    /// real deployment; use this only in trusted/admin/seeding contexts.
    pub fn all_crud_routes(&self) -> Router {
        use presentation::http::{
            create_bank_routes,
            create_data_consent_routes,
            create_data_subject_request_routes,
            create_employee_routes,
            create_employee_bank_account_routes,
            create_employee_bpjs_routes,
            create_employee_certification_routes,
            create_employee_contact_routes,
            create_employee_education_routes,
            create_employee_family_routes,
            create_employee_identity_routes,
            create_employee_tax_routes,
            create_employee_work_experience_routes,
            create_employment_routes,
            create_employment_history_routes,
            create_pii_access_log_routes,
            create_religion_routes,
        };

        Router::new()
            .merge(create_bank_routes(self.bank_service.clone()))
            .merge(create_data_consent_routes(self.data_consent_service.clone()))
            .merge(create_data_subject_request_routes(self.data_subject_request_service.clone()))
            .merge(create_employee_routes(self.employee_service.clone()))
            .merge(create_employee_bank_account_routes(self.employee_bank_account_service.clone()))
            .merge(create_employee_bpjs_routes(self.employee_bpjs_service.clone()))
            .merge(create_employee_certification_routes(self.employee_certification_service.clone()))
            .merge(create_employee_contact_routes(self.employee_contact_service.clone()))
            .merge(create_employee_education_routes(self.employee_education_service.clone()))
            .merge(create_employee_family_routes(self.employee_family_service.clone()))
            .merge(create_employee_identity_routes(self.employee_identity_service.clone()))
            .merge(create_employee_tax_routes(self.employee_tax_service.clone()))
            .merge(create_employee_work_experience_routes(self.employee_work_experience_service.clone()))
            .merge(create_employment_routes(self.employment_service.clone()))
            .merge(create_employment_history_routes(self.employment_history_service.clone()))
            .merge(create_pii_access_log_routes(self.pii_access_log_service.clone()))
            .merge(create_religion_routes(self.religion_service.clone()))
    }

    /// Deprecated alias for [`Self::all_crud_routes`]. `routes()` reads like
    /// "the routes" but mounts UNVALIDATED generic CRUD on every entity — a naive
    /// mount exposes unguarded writes. Compose a guarded router (read + validated
    /// writes) for production, or call `all_crud_routes()` to opt into the full
    /// unguarded surface explicitly.
    #[deprecated(note = "mounts unvalidated generic CRUD on every entity; compose a guarded router for production, or call all_crud_routes() for the intentional full/unguarded surface")]
    pub fn routes(&self) -> Router {
        self.all_crud_routes()
    }
}

